'use strict';

// MODULES //

var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' );
var isObject = require( '@stdlib/assert/is-plain-object' );
var startcase = require( '@stdlib/string/base/startcase' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Serializes a k-means clustering results object as a formatted string.
*
* ## Notes
*
* -   Example output:
*
*     ```text
*
*     K-means clustering using Lloyd algorithm
*
*         metric used: squared euclidean
*         total replicates: 4
*         best replicate: 2
*         total iterations: 10
*         inertia: 3.2800
*
*     Clustering ran for 4 clusters and 10 data samples, each with 3 features
*
*     ```
*
* @param {Object} results - k-means clustering results object
* @param {Options} [opts] - options object
* @param {PositiveInteger} [opts.digits=4] - number of digits to display after decimal points
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @returns {string} serialized results
*
* @example
* var results = {
*     'replicates': 4,
*     'replicate': 2,
*     'metric': 'sqeuclidean',
*     'iterations': 10,
*     'algorithm': 'lloyd',
*     'inertia': 3.28,
*     'k': 4,
*     'samples': 10,
*     'features': 3,
*     'method': 'K-means clustering'
* };
*
* var str = toString( results );
* // returns <string>
*/
function toString( results, opts ) { // eslint-disable-line stdlib/no-redeclare
	var metric;
	var dgts;
	var out;

	dgts = 4;
	if ( arguments.length > 1 ) {
		if ( !isObject( opts ) ) {
			throw new TypeError( format( 'invalid argument. Must provide an object. Value: `%s`.', opts ) );
		}
		if ( hasOwnProp( opts, 'digits' ) ) {
			if ( !isPositiveInteger( opts.digits ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be a positive integer. Option: `%s`.', 'digits', opts.digits ) );
			}
			dgts = opts.digits;
		}
	}

	if ( results.metric === 'sqeuclidean' ) {
		metric = 'squared euclidean';
	} else if ( results.metric === 'cityblock' ) {
		metric = 'cityblock';
	} else if ( results.metric === 'correlation' ) {
		metric = 'correlation';
	} else {
		metric = 'cosine';
	}

	out = [
		'',
		format( '%s using %s algorithm', results.method, startcase( results.algorithm ) ),
		'',
		format( '    metric used: %s', metric ),
		format( '    total replicates: %u', results.replicates ),
		format( '    best replicate: %u', results.replicate ),
		format( '    total iterations: %u', results.iterations ),
		format( '    inertia: %0.'+dgts+'f', results.inertia ),
		'',
		format( 'Clustering ran for %u clusters and %u data samples, each with %u features', results.k, results.samples, results.features )
	];
	return out.join( '\n' );
}


// EXPORTS //

module.exports = toString;
